from pathlib import Path
from PIL import Image
import numpy as np,json
R=Path(__file__).resolve().parents[1];O=R/'art/studies/final-geometry-242';C=O/'comparison';C.mkdir(exist_ok=True)
for label,path in [('before',R/'art/studies/hybrid-finish-241/main-4k.png'),('after',O/'main-4k.png')]:
 im=Image.open(path).convert('RGB')
 for name,box in [('road',(900,1250,2960,2460)),('characters',(1600,1720,2540,2420)),('break',(0,0,460,660)),('box',(1030,120,1450,850)),('footing',(450,1230,1120,1720)),('roof',(1450,75,2430,460)),('mounts',(350,600,1150,1240)),('arcade',(1400,850,2580,1330)),('left',(0,520,1300,1850))]:im.crop(box).save(C/(label+'-'+name+'.png'))
 im.resize((1920,1442),Image.Resampling.LANCZOS).save(C/(label+'-full.jpg'),quality=96)
assert (C/'before-full.jpg').read_bytes() != (C/'after-full.jpg').read_bytes(), 'Comparison images must differ'
b=np.asarray(Image.open(O/'main-4k.png').convert('RGB'));checks={}
for row in json.loads((R/'art/studies/pixel-characters-217/assets.json').read_text()):
 target=np.asarray(Image.open(R/row['placed_canvas']).convert('RGBA'));mask=target[:,:,3]==255;assert np.array_equal(b[mask],target[:,:,:3][mask]);checks[row['name']]='exact'
(O/'pixel-check.json').write_text(json.dumps(checks,indent=2))
(R/'prototype/review-242.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>242 · Service fit and chipped edges</title><style>body{margin:0;background:#191820;color:#e4ded7;font:16px system-ui}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:25px}h2{font-size:20px;margin-top:36px}p{line-height:1.5;color:#c3bab4}button{background:#33303e;color:inherit;border:1px solid #777080;padding:12px 18px;border-radius:6px;cursor:pointer;margin:4px}button.active{background:#775347}img{display:block;width:100%;height:auto;margin:18px auto}#characters{max-width:940px}#break,#box{max-width:650px}a{color:#e8c8a4}</style><main><h1>242 · Service fit and chipped edges</h1><p>Finer chipped facade recesses and Colosseum roof edges. Pipe supports route around the adjacent duct, the service terminals share a concrete footing, and the pier is trimmed inside the receiver box. Accepted lighting, blue palette, fog and character art are retained.</p><button onclick="choose('before',this)">Before · 241</button><button class="active" onclick="choose('after',this)">Refinements · 242</button><img id="full" src="../art/studies/final-geometry-242/comparison/after-full.jpg" alt="Whole scene"><p><a href="../art/studies/final-geometry-242/main-4k.png">Full-resolution scene</a> · <a href="../art/studies/final-geometry-242/scene.blend">Editable scene</a></p><h2>Lower arcade atmosphere</h2><img id="arcade" src="../art/studies/final-geometry-242/comparison/after-arcade.png" alt="Textured lower arcade atmosphere"><h2>Left blue palette</h2><img id="left" src="../art/studies/final-geometry-242/comparison/after-left.png" alt="Cool left facade balance"><h2>Character grounding</h2><img id="characters" src="../art/studies/final-geometry-242/comparison/after-characters.png" alt="Exact pixel characters with cast shadows"><h2>Road surface</h2><img id="road" src="../art/studies/final-geometry-242/comparison/after-road.png" alt="Uneven painted road surface"><h2>Shared service footing</h2><img id="footing" src="../art/studies/final-geometry-242/comparison/after-footing.png" alt="Shared concrete footing"><h2>Mount clearances</h2><img id="mounts" src="../art/studies/final-geometry-242/comparison/after-mounts.png" alt="Rerouted pipe supports"><h2>Roofline chips</h2><img id="roof" src="../art/studies/final-geometry-242/comparison/after-roof.png" alt="Colosseum roofline chips"><h2>Cited facade break</h2><img id="break" src="../art/studies/final-geometry-242/comparison/after-break.png" alt="Finer chipped impact hole"><h2>Receiver box</h2><img id="box" src="../art/studies/final-geometry-242/comparison/after-box.png" alt="Pier ends inside receiver box"></main><script>function choose(v,b){document.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');for(let id of ['road','characters','arcade','left','full','footing','roof','mounts','break','box'])document.getElementById(id).src='../art/studies/final-geometry-242/comparison/'+v+'-'+id+(id==='full'?'.jpg':'.png')+'?v=242-v1';location.hash=v}function sync(){let v=location.hash==='#before'?'before':'after';choose(v,document.querySelectorAll('button')[v==='before'?0:1])}window.addEventListener('hashchange',sync);sync();</script></html>''')
print('242 published; character pixels exact')
